-- SEC-50, SEC-52). Generated by `prisma migrate diff`, then the CHECK constraints were written by
-- hand (Prisma does not model them). Keep them equal in meaning to ../../../sqlite/migrations.
-- Nothing here holds a password, a session token, a TOTP secret or a recovery code in the clear:
-- the CHECKs refuse a password hash that is not Argon2id and ids that are not what the API makes.

-- CreateTable
CREATE TABLE "account" (
    "id" TEXT NOT NULL CHECK ("id" ~ '^[A-Za-z0-9_-]{22}$'),
    "email" TEXT NOT NULL CHECK (char_length("email") BETWEEN 3 AND 254 AND "email" = lower("email") AND "email" ~ '^[^@ ]+@[^@ ]+$'),
    "password_hash" TEXT NOT NULL CHECK (left("password_hash", 10) = '$argon2id$' AND char_length("password_hash") <= 256),
    "password_changed_at" TEXT NOT NULL CHECK ("password_changed_at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$'),
    "created_at" TEXT NOT NULL CHECK ("created_at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$'),

    CONSTRAINT "account_pkey" PRIMARY KEY ("id")
);

