    "expires_at" TEXT NOT NULL CHECK ("expires_at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$' AND "expires_at" > "created_at"),
    "revoked_at" TEXT CHECK ("revoked_at" IS NULL OR "revoked_at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$'),

    CONSTRAINT "session_pkey" PRIMARY KEY ("id")
);

