-- CreateTable
-- The sign/release permission is a column of its own (SEC-52) and only roles that can edit
-- configuration can hold it: Viewer and Billing never.
CREATE TABLE "membership" (
    "organisation_id" TEXT NOT NULL,
    "account_id" TEXT NOT NULL,
    "role" TEXT NOT NULL CHECK ("role" IN ('owner', 'admin', 'editor', 'viewer', 'billing')),
    "release_granted" BOOLEAN NOT NULL,
    "created_at" TEXT NOT NULL CHECK ("created_at" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]\.[0-9]{3}Z$'),

    CONSTRAINT "membership_pkey" PRIMARY KEY ("organisation_id","account_id"),
    CONSTRAINT "membership_release_role" CHECK (NOT "release_granted" OR "role" IN ('owner', 'admin', 'editor'))
);

